              style={{
                position: "absolute",
                left: `calc(${caretX * 100}% + ${4 * u}px)`,
                top: -4 * u,
                width: 2 * u,
                height: 18 * u,
                borderRadius: u,
                background: accent,
                opacity: blink,
              }}
            />
          )}
        </div>
      ))}
    </div>
  );
}

function FilmStrip({
  p,
  u,
  pal,
  accent,
}: {
  p: number;
  u: number;
  pal: Palette;
  accent: string;
}) {
  const n = 5;
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 * u }}>
      <div style={{ display: "flex", gap: 10 * u }}>
        {Array.from({ length: n }, (_, i) => {
          const done = interpolate(p, [i / n, (i + 0.8) / n], [0, 1], CLAMP);
          return (
            <div
              key={i}
              style={{
                position: "relative",
                width: 78 * u,
                height: 50 * u,
                borderRadius: 8 * u,
                background: pal.card,
                boxShadow: `0 0 0 ${Math.max(1, u)}px ${pal.hair}, 0 ${10 * u}px ${24 * u}px -${12 * u}px ${pal.cardShadow}`,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background: `linear-gradient(160deg, ${pal.block}, ${pal.line})`,
                  clipPath: `inset(0 ${(1 - done) * 100}% 0 0)`,
                }}
              />
              <div
                style={{
                  position: "absolute",
                  left: 9 * u,
                  bottom: 9 * u,
                  width: 26 * u,
                  height: 5 * u,
                  borderRadius: 99,
                  background: i === 2 ? accent : pal.line,
                  opacity: done,
                }}
              />
            </div>
          );
        })}
      </div>
      <div
        style={{
          height: Math.max(1, 1.5 * u),
          background: pal.hair,
          borderRadius: 99,
          position: "relative",
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            right: `${(1 - p) * 100}%`,
            background: pal.fg,
            opacity: 0.55,
            borderRadius: 99,
          }}
        />
      </div>
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

/* ------------------------------------------------------------------ */

function PaperPlaneBase(props: PaperPlaneProps) {
  const {
    steps = ["Write", "Render", "Launch"],
    logo,
    url = "remocn.dev",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = display,
    trail = true,
    scale = 1,
    delay = 0,
    grain = true,
    speed = 1,
    theme = "light",
    timing,
  } = props;
  const glide = useGlide();
  const frame = useSceneFrame();
  const tAt = (f: number) => Math.max(0, f - delay) * speed;
  const t = tAt(frame);
  const transparent = background === "transparent";
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    paperPlaneTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const intro = tl.get("intro");
  const flight = tl.get("flight");
  const landing = tl.get("landing");
  const urlEl = tl.get("url");
  const land = landing.start;
  const u = height / 720;
  const pal = THEMES[theme];
  const W = width;
  const D = width * 0.92;

  // lockup geometry (world space, origin = centre of the first stop)
  const F = 128 * u;
  const dotR = 0.068 * F;
  const lockW = logo ? 4 * F : F * (LOGO_R + 0.04 + LOGO_EMOCN);
  const lockX = 2 * D - (lockW + 0.06 * F + dotR * 2) / 2;
  const lockY = 30 * u;
  const baseY = lockY + 0.36 * F;
  const dotX = lockX + lockW + 0.06 * F + dotR;
  const dotY = baseY - dotR;
  const dot: V2 = { x: dotX, y: dotY };

  const track = useMemo(() => {
    const dot: V2 = { x: dotX, y: dotY };
    // the loop sits above-left of the logo, clear of the letters
    const C = { x: 2 * D - 360 * u, y: lockY - 170 * u };
    const R = 88 * u;
    const loop: V2[] = [];
    for (let k = 0; k <= 12; k++) {
      const a = Math.PI / 2 - (k * Math.PI * 2) / 12;
      loop.push({ x: C.x + Math.cos(a) * R, y: C.y + Math.sin(a) * R });
    }
    return buildTrack([
      { x: -0.66 * W, y: 250 * u },
      { x: -0.32 * W, y: 196 * u },
      { x: 0.02 * W, y: 214 * u },
      { x: 0.32 * W, y: 120 * u },
      { x: 0.6 * W, y: -150 * u },
      { x: D - 0.1 * W, y: -252 * u },
      { x: D + 0.17 * W, y: -180 * u },
      { x: D + 0.36 * W, y: 40 * u },
      { x: C.x - 130 * u, y: C.y + R + 8 * u },
      ...loop,
      // skim over the word, drop past its end and hook back into the full stop
      { x: lockX + lockW * 0.4, y: lockY - 150 * u },
      { x: dot.x + 64 * u, y: lockY - 118 * u },
      { x: dot.x + 90 * u, y: dot.y + 2 * u },
      { x: dot.x + 36 * u, y: dot.y + 22 * u },
      dot,
    ]);
  }, [W, D, u, dotX, dotY, lockX, lockY, lockW]);
  const flightLength = flight.length;
  const flightEase = flight.beat("ease");
  const dist = useMemo(
    () => buildDistance(flightLength, flightEase),
    [flightLength, flightEase],
  );

  const sAt = (time: number) => {
    const x = Math.min(flightLength, Math.max(0, time - flight.start)) * 2;
    const i = Math.floor(x);
    const f = x - i;
    const a = dist[Math.min(i, dist.length - 1)];
    const b = dist[Math.min(i + 1, dist.length - 1)];
    return (a + (b - a) * f) * track.total;
  };
  const s = sAt(t);
  const pos = sampleTrack(track, s);
  const heading = headingAt(track, s);

  // bank into the turn, plus a slow rock so the facets keep catching light
  const turn = headingAt(track, s + 30 * u) - headingAt(track, s - 30 * u);
  const wrapped = Math.atan2(Math.sin(turn), Math.cos(turn));
  const bank =
    Math.max(-0.6, Math.min(0.6, wrapped * 0.9)) + Math.sin(t / 13) * 0.22;
  const tilt = 0.95 + Math.sin(t / 21) * 0.08;

  // camera: follows the plane with a soft lag, then settles on the lockup
  const softMax = (a: number, b: number, k: number) =>
    (a + b + Math.sqrt((a - b) ** 2 + k * k)) / 2;
  const cameraAt = (time: number) => {
    let lagX = 0;
    let lagY = 0;
    for (let k = 0; k < 6; k++) {
      const p = sampleTrack(track, sAt(time - 6 - k * 3));
      lagX += p.x / 6;
      lagY += p.y / 6;
    }
    const settle = interpolate(
      time,
      [land + landing.beat("cameraAt"), land + landing.beat("cameraEnd")],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_IO,
      },
    );
    const followX = softMax(lagX + 0.08 * W, 0, 180 * u);
    return {
      camX: followX + (2 * D - followX) * settle,
      camY: lagY * 0.28 * (1 - settle),
      zoom: 1 + 0.035 * settle,
    };
  };
  const { camX, camY, zoom } = cameraAt(t);
  // The camera eases onto the lockup slowly, so it counts as moving while any
  // text on screen, at most ~800px from the centre, shifts by a thousandth of
  // a pixel between frames.
  const camMoving = [cameraAt(tAt(frame - 1)), cameraAt(tAt(frame + 1))].some(
    (o) =>
      Math.abs(o.camX - camX) * zoom +
        Math.abs(o.camY - camY) * zoom +
        Math.abs(o.zoom - zoom) * 800 >
      1e-3,
  );

  // landing: the plane folds itself into the accent dot
  const morph = interpolate(t, [land + landing.beat("morphAt"), land], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.55, 0, 1, 0.45),
  });
  const planeSize = 62 * u * (1 - morph * 0.86);
  const height3d = interpolate(
    t,
    [land + landing.beat("descendAt"), land],
    [1, 0],
    {
      ...CLAMP,
      easing: Easing.bezier(0.55, 0, 1, 0.45),
    },
  );
  const lift = { x: 10 * u * height3d + 2 * u, y: 30 * u * height3d + 3 * u };
  const facets = planeFacets(heading, bank, tilt, planeSize, lift);
  const accentRgb = hexRgb(accent);
  const dotIn = interpolate(
    t,
    [land + landing.beat("dotAt"), land + landing.beat("dotEnd")],
    [0, 1],
    CLAMP,
  );
  const dotPop = interpolate(
    t,
    [land, land + landing.beat("popPeak"), landing.end],
    [1, 1.12, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );

  // the dashed trail, oldest part faded
  const trailEnd = Math.max(0, s - planeSize * 0.72);
  const dash = 7 * u;
  const gap = 9 * u;
  const chunks: React.ReactNode[] = [];
  const CH = 140 * u;
  const trailDim = interpolate(
    t,
    [land + landing.beat("dimAt"), land + landing.beat("dimEnd")],
    [1, 0.4],
    CLAMP,
  );
  for (let c0 = 0; c0 < trailEnd; c0 += CH) {
    const c1 = Math.min(trailEnd, c0 + CH);
    const pts: string[] = [];
    for (let d = c0; d <= c1 + 0.01; d += 6 * u) {
      const p = sampleTrack(track, Math.min(d, c1));
      pts.push(`${p.x.toFixed(1)},${p.y.toFixed(1)}`);
    }
    const behind = trailEnd - c1;
    chunks.push(
      <polyline
        key={c0}
        points={pts.join(" ")}
        fill="none"
        stroke={pal.trail}
        strokeWidth={1.4 * u}
        strokeLinecap="round"
        strokeDasharray={`${dash} ${gap}`}
        strokeDashoffset={-(c0 % (dash + gap))}
        opacity={interpolate(behind, [0, 1800 * u], [1, 0.3], CLAMP) * trailDim}
      />,
    );
  }

  // stop reactions, driven by where the plane is
  const writeP = interpolate(pos.x, [-0.42 * W, 0.42 * W], [0, 1], CLAMP);
  const renderP = interpolate(
    pos.x,
    [D - 0.3 * W, D + 0.36 * W],
    [0, 1],
    CLAMP,
  );
  const s1 = interpolate(t, [intro.start, intro.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const s2 = interpolate(camX, [0.35 * D, 0.75 * D], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const s3 = interpolate(camX, [1.3 * D, 1.75 * D], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const wordReveal = interpolate(camX, [1.5 * D, 1.85 * D], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const urlIn = interpolate(t, [urlEl.start, urlEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const rise = (p: number) => ({
    opacity: p,
    transform: `translateY(${(1 - p) * 16 * u}px)${glide(midway(p) && !camMoving)}`,
  });

  const shadowBlur = (2 + height3d * 5) * u;
  const svgId = `pp${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? pal.bg),
        overflow: "hidden",
      }}
    >
      {background === undefined ? (
        <>
          {pal.texture > 0 && (
            <AbsoluteFill
              style={{
                backgroundImage: PAPER_TEX,
                backgroundSize: `${240 * u}px ${240 * u}px`,
                backgroundPosition: `${-camX * 0.98}px ${-camY}px`,
              }}
            />
          )}
          <AbsoluteFill
            style={{
              background: `radial-gradient(ellipse 70% 80% at 40% 30%, ${
                theme === "light"
                  ? "rgba(255,255,255,0.6)"
                  : "rgba(255,255,255,0.035)"
              }, transparent 100%)`,
            }}
          />

          <AbsoluteFill
            style={{ backgroundImage: groundFill(theme, camX / (2 * D)) }}
          />
        </>
      ) : null}

      {/* world */}
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            left: W / 2,
            top: height / 2,
            width: 0,
            height: 0,
            transform: `scale(${zoom}) translate(${-camX}px, ${-camY}px)${glide(camMoving)}`,
          }}
        >
          {/* stop 1: write */}
          <div
            style={{
              position: "absolute",
              left: -0.36 * W,
              top: -150 * u,
              ...rise(s1),
            }}
          >
            <StepLabel index="01" u={u} pal={pal} />
            <BigWord
              text={steps[0]}
              u={u}
              pal={pal}
              font={fontFamily}
              ink={ink}
            />
          </div>
          <div
            style={{
              position: "absolute",
              left: 0.07 * W,
              top: -110 * u,
              transform: `rotate(-3deg) translateY(${(1 - s1) * 20 * u}px)`,
              opacity: s1,
            }}
          >
            <WriteCard p={writeP} t={t} u={u} pal={pal} accent={accent} />
          </div>

          {/* stop 2: render */}
          <div
            style={{
              position: "absolute",
              left: D - 0.3 * W,
              top: -150 * u,
              ...rise(s2),
            }}
          >
            <FilmStrip p={renderP} u={u} pal={pal} accent={accent} />
          </div>
          <div
            style={{
              position: "absolute",
              left: D - 0.3 * W,
              top: -10 * u,
              ...rise(s2),
            }}
          >
            <StepLabel index="02" u={u} pal={pal} />
            <BigWord
              text={steps[1]}
              u={u}
              pal={pal}
              font={fontFamily}
              ink={ink}
            />
          </div>

          {/* stop 3: launch, the lockup the plane lands in */}
          <div
            style={{
              position: "absolute",
              left: lockX,
              width: lockW,
              display: "flex",
              justifyContent: "flex-end",
              top: baseY - 0.72 * F - 64 * u,
              ...rise(s3),
            }}
          >
            <StepLabel index="03" text={steps[2]} u={u} pal={pal} />
          </div>
          <div
            style={{
              position: "absolute",
              left: lockX,
              top: baseY - LOGO_BASELINE * F,
              height: F,
              display: "flex",
              alignItems: "baseline",
              color: ink ?? pal.fg,
              fontFamily: sans,
              fontWeight: 600,
              fontSize: F,
              lineHeight: 1,
              letterSpacing: "-0.025em",
            }}
          >
            {logo ?? (
              <>
                <svg
                  viewBox="0 0 124.06 134.26"
                  style={{
                    height: "0.76em",
                    width: "auto",
                    opacity: s3,
                    transform: `translateY(${(1 - s3) * 16 * u}px)`,
                  }}
                  aria-hidden
                >
                  <path fill="currentColor" d={REMOCN_R_PATH} />
                </svg>
                <span
                  style={{
                    marginLeft: "0.04em",
                    clipPath: `inset(-20% ${(1 - wordReveal) * 100}% -20% 0)`,
                    transform: `translateX(${(1 - wordReveal) * -20 * u}px)`,
                  }}
                >
                  emocn
                </span>
              </>
            )}
          </div>
          <div
            style={{
              position: "absolute",
              left: lockX,
              width: lockW,
              top: baseY + 44 * u,
              textAlign: "center",
              fontFamily: sans,
              fontSize: 21 * u,
              fontWeight: 500,
              letterSpacing: "-0.01em",
              color: pal.muted,
              ...rise(urlIn),
            }}
          >
            {url}
          </div>

          {/* trail + plane */}
          <svg
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              overflow: "visible",
            }}
            width={1}
            height={1}
            aria-hidden
          >
            <defs>
              <filter id={svgId} x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={shadowBlur} />
              </filter>
            </defs>
            {trail ? chunks : null}
            {morph < 1 && (
              <g transform={`translate(${pos.x} ${pos.y})`}>
                <g filter={`url(#${svgId})`} opacity={1 - morph}>
                  {facets.map((fc, i) => (
                    <polygon
                      key={`s${i}`}
                      points={fc.shadowPts}
                      fill={pal.shadow}
                      opacity={0.22 + (1 - height3d) * 0.3}
                    />
                  ))}
                </g>
                {facets.map((fc, i) => (
                  <polygon
                    key={i}
                    points={fc.pts}
                    fill={rgb(
                      mix(mix(pal.fold, pal.paper, fc.lit), accentRgb, morph),
                    )}
                    stroke={pal.edge}
                    strokeWidth={0.6 * u}
                    strokeLinejoin="round"
                  />
                ))}
              </g>
            )}
            {dotIn > 0 && (
              <circle
                cx={dot.x}
                cy={dot.y}
                r={dotR * dotPop}
                fill={accent}
                opacity={dotIn}
              />
            )}
          </svg>
        </div>
      </ScaleLayer>

      {!transparent && grain ? <Grain opacity={pal.grain} /> : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "light",
    variants: {
      light: {},
      dark: {},
    },
    description: "Theme",
  },
  url: {
    type: "text-content",
    default: "remocn.dev",
    description: "Url",
  },
  land: {
    type: "number",
    default: 184,
    min: 90,
    max: 300,
    step: 2,
    description: "Landing (frame)",
    hiddenFromList: false,
  },
  trail: {
    type: "boolean",
    default: true,
    description: "Trail",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Fraunces",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","url","land","trail","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "light",
  url: "remocn.dev",
  land: 184,
  trail: true,
  accent: "#3B5BFD",
  fontFamily: "Fraunces",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type PaperPlaneElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PaperPlaneBase>;

const PaperPlaneInner = forwardRef<
  HTMLDivElement,
  PaperPlaneElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PaperPlane>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PaperPlaneBase
          {...(componentProps as unknown as ComponentProps<typeof PaperPlaneBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PaperPlane = Interactive.withSchema({
  Component: PaperPlaneInner,
  componentName: "<PaperPlane>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
